# AI Office v2.6 Part A Memory Context Architecture Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
if(-not(Test-Path $Repository)){throw "AI Office repository not found."}
Set-Location $Repository
$Stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$Backup=Join-Path $Repository ("workspace\installer-backups\v2.6-part-a-"+$Stamp)
New-Item -ItemType Directory -Path $Backup -Force|Out-Null
foreach($D in @("config\memory","scripts\memory","workspace\memory\indexes","workspace\memory\records","workspace\memory\context-snapshots","docs")){New-Item -ItemType Directory -Path (Join-Path $Repository $D) -Force|Out-Null}
function Write-EmbeddedFile{
 param([string]$RelativePath,[string]$Data)
 $Dest=Join-Path $Repository $RelativePath
 New-Item -ItemType Directory -Path (Split-Path -Parent $Dest) -Force|Out-Null
 if(Test-Path $Dest){
  $B=Join-Path $Backup $RelativePath
  New-Item -ItemType Directory -Path (Split-Path -Parent $B) -Force|Out-Null
  Copy-Item $Dest $B -Force
 }
 [IO.File]::WriteAllBytes($Dest,[Convert]::FromBase64String($Data))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\memory-policy.json" -Data ""
Write-EmbeddedFile -RelativePath "config\memory\memory-record-schema.json" -Data ""
Write-EmbeddedFile -RelativePath "workspace\memory\indexes\memory-index.json" -Data "ewogICJzY2hlbWFfdmVyc2lvbiI6ICIxLjAuMCIsCiAgInZlcnNpb24iOiAiMi42LjAiLAogICJyZWNvcmRfY291bnQiOiAwLAogICJyZWNvcmRzIjogW10sCiAgInVwZGF0ZWRfYXQiOiAiIgp9Cg=="
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeMemoryPolicy.ps1" -Data "cGFyYW0oKQokRXJyb3JBY3Rpb25QcmVmZXJlbmNlPSJTdG9wIgpHZXQtQ29udGVudCAiRTpcQUlcQUktT2ZmaWNlXGNvbmZpZ1xtZW1vcnlcbWVtb3J5LXBvbGljeS5qc29uIiAtUmF3IHwgQ29udmVydEZyb20tSnNvbgo="
Write-EmbeddedFile -RelativePath "scripts\memory\Get-AIOfficeMemoryArchitecture.ps1" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\Test-AIOfficeMemoryContextArchitecture.ps1" -Data ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Part-A-Memory-Context-Architecture.md" -Data ""
$Scripts=Get-ChildItem "E:\AI\AI-Office\scripts\memory\*.ps1" -File
foreach($Script in $Scripts){$T=$null;$E=$null;[System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$T,[ref]$E)|Out-Null;if($E.Count-gt0){throw ("Syntax error in "+$Script.FullName+": "+(($E|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.6 Part A Memory & Context Architecture installed successfully." -ForegroundColor Green
Write-Host "Memory retrieval remains disabled; v2.5.1 live behavior is unchanged." -ForegroundColor Cyan
Write-Host "Backups: $Backup" -ForegroundColor Cyan